"""Generate an offline-capable glossary from its reviewed bilingual source."""
import json
from html import escape as e
from pathlib import Path

root=Path(__file__).resolve().parents[1]
unit=root/'unidades/u08-redes-neuronales-lstm-gnn-blockchain'
data=json.loads((unit/'recursos/glosario-datos.json').read_text())
labs=json.loads((unit/'simuladores/labs.json').read_text())['labs']
categories={'Fundamentos':'Foundations','Series temporales':'Time series','Datos y variables':'Data and variables','Validación':'Validation','Preprocesamiento':'Preprocessing','Modelos':'Models','Redes neuronales':'Neural networks','Entrenamiento':'Training','Métricas':'Metrics','Mercado':'Market','Grafos':'Graphs','GNN':'GNN','Grafos dinámicos':'Dynamic graphs','Interpretabilidad':'Interpretability','On-chain':'On-chain','Metodología':'Methodology'}
def bi(es,en,tag='span',cls=''):
    return ''.join(f'<{tag} data-lang="{lang}"'+(f' class="{cls}"' if cls else '')+f'>{e(text)}</{tag}>' for lang,text in [('es',es),('en',en)])
def ui(es,en,tag='span'):
    return f'<{tag} data-es="{e(es,quote=True)}" data-en="{e(en,quote=True)}">{e(es)}</{tag}>'
cards=[]
terms={x['id']:x for x in data['terms']}
for item in sorted(data['terms'],key=lambda x:x['term'].casefold()):
    related=''.join(f'<a href="#{e(k)}">{e(terms[k]["term"])}</a>' for k in item['related'])
    lablinks=''.join(f'<a href="../simuladores/{e(labs[n-1]["file"])}">'+ui(f'Laboratorio {n:02}',f'Lab {n:02}')+'</a>' for n in item['labs'])
    formula=f'<div class="formula">{e(item["formula"])}</div>' if item['formula'] else ''
    cards.append(f'<details class="glossary-card" id="{e(item["id"])}"><summary><span><span class="term-name">{e(item["term"])}</span><span class="term-meta">'+ui(item['category'],categories[item['category']])+'</span></span><span class="term-sign" aria-hidden="true">＋</span></summary><div class="glossary-body">'+bi(item['es'],item['en'],'p')+formula+ui('Ejemplo y contexto','Example and context','h3')+bi(item['example']['es'],item['example']['en'],'p')+'<div class="critical">'+ui('Lectura crítica','Critical interpretation','h3')+bi(item['caution']['es'],item['caution']['en'],'p')+'</div>'+ui('Conectar y experimentar','Connect and experiment','h3')+f'<div class="term-links">{related}{lablinks}<button type="button" data-copy-term="{e(item["id"])}">'+ui('Copiar enlace','Copy link')+'</button></div><div class="term-tags">'+e(item['tags'])+'</div></div></details>')
options=''.join(f'<option value="{e(k)}" data-es="{e(k)}" data-en="{e(v)}">{e(k)}</option>' for k,v in sorted(categories.items()))
sources=[('Bitcoin · Transactions','https://developer.bitcoin.org/devguide/transactions.html'),('Ethereum · Gas and fees','https://ethereum.org/en/developers/docs/gas/'),('PyTorch · LSTM','https://docs.pytorch.org/docs/stable/generated/torch.nn.LSTM.html'),('PyTorch · GRU','https://docs.pytorch.org/docs/stable/generated/torch.nn.GRU.html'),('GCN · Kipf & Welling','https://arxiv.org/abs/1609.02907'),('GraphSAGE · Hamilton et al.','https://arxiv.org/abs/1706.02216'),('GAT · Veličković et al.','https://arxiv.org/abs/1710.10903'),('SHAP · LinearExplainer','https://shap.readthedocs.io/en/latest/generated/shap.LinearExplainer.html'),('SHAP · Lundberg & Lee','https://arxiv.org/abs/1705.07874'),('TikTok · How recommendations work','https://support.tiktok.com/en/using-tiktok/exploring-videos/how-tiktok-recommends-content')]
source_html=''.join(f'<a href="{e(url)}" target="_blank" rel="noopener noreferrer">{e(title)} ↗</a>' for title,url in sources)
css=(unit/'assets/lab.css').read_text()+'\n'+(unit/'assets/glossary.css').read_text()
js=(unit/'assets/glossary.js').read_text()
article='https://sgevatschnaider.github.io/es/articulos/tiktok/index.html'
page='''<!doctype html><html lang="es" data-theme="dark"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="author" content="Sergio Gevatschnaider"><meta name="description" content="145 términos desarrollados de redes neuronales, LSTM, GRU, GNN, validación y blockchain. Definiciones ES/EN, ejemplos, fórmulas y laboratorios."><title>Glosario · Unidad 8 · Redes neuronales y blockchain</title><style>'''+css+'''</style></head><body><a class="skip" href="#terminos">'''+ui('Saltar a los términos','Skip to terms')+'''</a><main class="shell"><nav class="lab-nav" aria-label="Unidad 8"><a href="../index.html">'''+ui('Unidad 8','Unit 8')+'''</a><a href="../materiales/">'''+ui('Presentaciones','Presentations')+'''</a><a href="../simuladores/">'''+ui('Laboratorios','Laboratories')+'''</a><a href="guia-simuladores.html">'''+ui('Guía completa','Complete guide')+'''</a><a href="'''+article+'''" target="_blank" rel="noopener noreferrer">'''+ui('Artículo: TikTok y GNN ↗','Article: TikTok and GNN ↗')+'''</a></nav><header class="topbar" id="inicio"><div class="brand"><div class="badge">U8</div><div><h1>'''+ui('Glosario de IA y blockchain','AI and blockchain glossary')+'''</h1><p>'''+ui('Comprender, relacionar y aplicar','Understand, connect and apply')+'''</p></div></div><div class="actions"><button id="lang" class="btn" type="button" aria-label="Cambiar a inglés">EN</button><button id="theme" class="btn" type="button" aria-pressed="false">Modo claro</button><a class="btn" id="download" href="glosario.html" download="Glosario_U8_Sergio_Gevatschnaider.html">'''+ui('Descargar HTML','Download HTML')+'''</a><button id="print" class="btn" type="button">'''+ui('Imprimir / PDF','Print / PDF')+'''</button></div></header><section class="hero glossary-hero"><div><p class="lab-kicker">'''+ui('Del concepto al experimento','From concept to experiment')+'''</p><h2>'''+ui('Un vocabulario para pensar con precisión','A vocabulary for precise thinking')+'''</h2>'''+bi('Redes neuronales, series temporales, grafos y explicabilidad aplicados a Bitcoin y Ethereum. Cada entrada desarrolla una definición, un ejemplo y una lectura crítica, y permite pasar al laboratorio relacionado.','Neural networks, time series, graphs and explainability applied to Bitcoin and Ethereum. Each entry develops a definition, an example and a critical interpretation, with links to the related laboratory.','p')+'''<div class="lab-type">'''+ui('ES / EN · Fórmulas · Ejemplos · Enlaces por término','ES / EN · Formulas · Examples · Term links')+'''</div></div><div class="glossary-stats"><div><strong>145</strong>'''+ui('Términos desarrollados','Developed terms')+'''</div><div><strong>16</strong>'''+ui('Áreas temáticas','Subject areas')+'''</div><div><strong>8</strong>'''+ui('Laboratorios conectados','Connected laboratories')+'''</div></div></section><p class="glossary-guide">'''+ui('Buscá en definiciones y ejemplos, filtrá por área o inicial y abrí un término. Los filtros se combinan; “Limpiar filtros” recupera todos. El HTML descargado funciona sin conexión; los enlaces al campus y fuentes requieren internet.','Search definitions and examples, filter by subject or initial, and open a term. Filters combine; “Clear filters” restores all entries. The downloaded HTML works offline; campus and source links require internet.')+'''</p><noscript><p class="callout">Las 145 entradas están disponibles. Para buscar y cambiar idioma o tema, activá JavaScript.</p></noscript><section class="glossary-tools" aria-label="Filtros del glosario"><div class="filter-row"><label class="field" for="search">'''+ui('Buscar en el glosario','Search the glossary')+'''<input id="search" type="search" placeholder="Buscar concepto, ejemplo o etiqueta…" autocomplete="off"></label><label class="field" for="category">'''+ui('Área temática','Subject area')+'''<select id="category"><option value="" data-es="Todas las áreas" data-en="All subject areas">Todas las áreas</option>'''+options+'''</select></label><button class="btn" id="resetFilters" type="button">'''+ui('Limpiar filtros','Clear filters')+'''</button></div><nav class="alphabet" id="alphabet" aria-label="Inicial del término"></nav><div class="active-filter" id="activeFilter"></div></section><div class="glossary-summary"><p id="resultCount" class="result-count" role="status" aria-live="polite">145 de 145 términos visibles</p><div class="actions"><button class="btn" id="expand" type="button">'''+ui('Expandir visibles','Expand visible')+'''</button><button class="btn" id="collapse" type="button">'''+ui('Cerrar todos','Collapse all')+'''</button></div></div><p id="copyStatus" class="muted" role="status" aria-live="polite"></p><div class="glossary-empty" id="empty" hidden>'''+ui('No hay coincidencias. Probá otra palabra o limpiá los filtros.','No matches. Try another word or clear the filters.')+'''</div><section class="glossary-grid" id="terminos" aria-label="Términos desarrollados">'''+''.join(cards)+'''</section><section class="panel glossary-reading" style="margin-top:32px"><div><p class="lab-kicker">'''+ui('Lectura complementaria · Sergio Gevatschnaider','Complementary reading · Sergio Gevatschnaider')+'''</p><h3>Cómo TikTok sabe lo que querés ver</h3>'''+bi('Conectá usuarios, videos, embeddings y propagación de mensajes con el análisis de blockchain. El ejemplo es una analogía didáctica y su fórmula no documenta la arquitectura interna de TikTok.','Connect users, videos, embeddings and message passing with blockchain analysis. The example is a teaching analogy; its formula does not document TikTok’s internal architecture.','p')+'''</div><a class="btn primary" data-tiktok href="'''+article+'''" target="_blank" rel="noopener noreferrer">'''+ui('Leer artículo: TikTok y GNN ↗','Read article: TikTok and GNN ↗')+'''</a></section><section class="panel" id="fuentes"><h2>'''+ui('Fuentes para profundizar','Sources for further study')+'''</h2><p class="muted">'''+ui('Referencias primarias y documentación. Las definiciones y ejemplos se adaptaron al alcance concreto de los laboratorios de la Unidad 8.','Primary references and documentation. Definitions and examples were adapted to the specific scope of Unit 8 laboratories.')+'''</p><div class="source-grid">'''+source_html+'''</div></section><footer class="footer"><strong>'''+data['author']+'''</strong>'''+ui('Versión revisada · 2 oct 2026 · 133 términos originales + 12 complementarios','Revised version · 2 Oct 2026 · 133 original terms + 12 additions')+'''</footer></main><a class="btn glossary-backtop" href="#inicio">'''+ui('↑ Buscar','↑ Search')+'''</a><script id="glossary-data" type="application/json">'''+json.dumps(data,ensure_ascii=False,separators=(',',':')).replace('<',r'\u003c')+'''</script><script>'''+js+'''</script></body></html>'''
(unit/'recursos/glosario.html').write_text(page)
print('Glosario generado: 145 entradas bilingües, autocontenido y con enlaces a laboratorios.')
